def main():
    TMP.mkdir(parents=True,exist_ok=True)
    original_sha=hashlib.sha256(SOURCE.read_bytes()).hexdigest()
    with ZipFile(SOURCE) as z:parts={p:z.read(p) for p in z.namelist()}
    root=E.fromstring(parts['word/document.xml']);body=root.find(W+'body')
    count_words=lambda node:len(' '.join(node.xpath('.//w:t/text()',namespaces=NS)).split())
    before=count_words(root);edits=[]
    for index,value in REPLACEMENTS.items():
        p=body[index];old=txt(p)
        assert p.tag==W+'p' and old.strip(),index
        assert not p.findall('.//'+W+'drawing')
        assert not p.find(W+'bookmarkStart') is not None,('Heading cannot change',index)
        assert re.findall(r'\[\d+\]',old)==re.findall(r'\[\d+\]',value),(index,'Citation loss')
        replace_text(p,value)
        edits.append({'body_index':index,'old_words':len(old.split()),'new_words':len(value.split()),'old':old,'new':value})
    after=count_words(root)
    original=E.fromstring(parts['word/document.xml'])
    # Headings/bookmarks, section geometry, tables and figures remain unchanged.
    for xpath in ['//w:tbl','//w:sectPr','//w:drawing','//w:bookmarkStart','//w:bookmarkEnd']:
        assert [E.tostring(e) for e in original.xpath(xpath,namespaces=NS)]==[E.tostring(e) for e in root.xpath(xpath,namespaces=NS)],xpath
    parts['word/document.xml']=E.tostring(root,encoding='UTF-8',xml_declaration=True,standalone=True)
    write_package(parts,OUT)
    write_package(parts,TMP/'before_word_refresh.docx')
    audit={'source':str(SOURCE),'source_sha256':original_sha,'output':str(OUT),'before_whitespace_words':before,'after_whitespace_words':after,'reduction':before-after,'edited_paragraphs':len(edits),'edits':edits}
    (TMP/'audit.json').write_text(json.dumps(audit,indent=2,ensure_ascii=False),encoding='utf-8')
    print(json.dumps({k:v for k,v in audit.items() if k!='edits'},indent=2))
    assert hashlib.sha256(SOURCE.read_bytes()).hexdigest()==original_sha


if __name__=='__main__':main()
